<script setup>
import {ref,onMounted,onBeforeUnmount} from 'vue'
import {api,accessToken} from '../lib/api.js'
import PageHeader from '../components/PageHeader.vue'
const levels={country:'国家/地区',province:'省级',city:'市级',district:'区/县',street:'街道/乡镇'}
const rows=ref([]),stats=ref(null),trail=ref([]),query=ref(''),page=ref(1),hasMore=ref(false),loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),form=ref(null),preview=ref(null),source=ref(''),sourceVersion=ref(''),importMode=ref('preserve');let generation=0
async function load(){const v=++generation,token=accessToken();loading.value=true;error.value='';try{const r=await api('/admin/regions?'+new URLSearchParams({parentCode:trail.value.at(-1)?.code||'',query:query.value,page:page.value}));if(v!==generation||token!==accessToken())return;if(stats.value&&stats.value.revision!==r.stats.revision){form.value=null;preview.value=null;notice.value='地区库版本已变化，请基于新版本重新编辑。'}rows.value=r.items;stats.value=r.stats;hasMore.value=r.hasMore;if(!source.value){source.value=r.source;sourceVersion.value=r.sourceVersion}}catch(e){if(v===generation){error.value=e.message;if([401,403].includes(e.status)){rows.value=[];stats.value=null;preview.value=null;form.value=null}}}finally{if(v===generation)loading.value=false}}
function browse(row){trail.value=row?row.path:[];query.value='';page.value=1;load()}
function edit(row){preview.value=null;form.value={code:row.code,parentCode:row.parentCode,name:row.name,level:row.level,enabled:row.enabled}}
function add(){const p=trail.value.at(-1);form.value={code:'',name:'',parentCode:p?.code||'',level:p?Object.keys(levels)[Object.keys(levels).indexOf(p.level)+1]||'street':'country',enabled:true};preview.value=null}
async function prepare(items,metadata={}){if(busy.value)return;busy.value=true;error.value='';notice.value='';preview.value=null;const token=accessToken();try{const result=await api('/admin/regions/preview',{method:'POST',body:{expectedRevision:stats.value?.revision,items,source:source.value,sourceVersion:sourceVersion.value,mode:'merge',...metadata}});if(token===accessToken())preview.value=result}catch(e){if(token===accessToken())error.value=e.message}finally{busy.value=false}}
async function importFile(e){const file=e.target.files?.[0];e.target.value='';if(!file)return;try{if(file.size>20*1024*1024)throw Error('文件须在20MB以内');const data=JSON.parse(await file.text()),isArray=Array.isArray(data),items=isArray?data:data?.items;if(!Array.isArray(items))throw Error('请选择包含 items 数组的地区库文件，或原始 pcas 省市区街道数组');const pcas=!items.some(row=>row&&(Object.hasOwn(row,'level')||Object.hasOwn(row,'parentCode'))),preserve=pcas||importMode.value==='preserve';await prepare(items,{source:isArray?'上传行政区域补充文件：'+file.name.slice(0,200):data.source||source.value||'上传行政区域补充文件',sourceVersion:isArray?file.name.slice(0,80):data.sourceVersion||sourceVersion.value||file.name.slice(0,80),mode:pcas?'merge':importMode.value==='replace'?'replace':'merge',conflictPolicy:preserve?'preserve':'replace'})}catch(e){error.value=e.message}}
async function apply(){if(busy.value||!preview.value)return;busy.value=true;error.value='';const token=accessToken();try{await api('/admin/regions/apply',{method:'POST',body:{token:preview.value.token}});if(token!==accessToken())return;notice.value='地区库已更新，所有选择入口立即使用新版本。';preview.value=null;form.value=null;await load()}catch(e){if(token===accessToken())error.value=e.message}finally{busy.value=false}}
async function download(){try{const data=await api('/admin/regions/export');const href=URL.createObjectURL(new Blob([JSON.stringify({source:data.source,sourceVersion:data.sourceVersion,items:data.items},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=href;a.download='地区库-'+data.revision+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(href),1000)}catch(e){error.value=e.message}}
onMounted(load);onBeforeUnmount(()=>{generation++})
</script>
<template><div><PageHeader title="行政区域库" description="统一维护国家、省、市、区县、街道乡镇。停用地区不再提供新选择，历史资料保留。"/><div class="regions-toolbar"><button class="button button-secondary" @click="load">刷新</button><button class="button button-secondary" @click="download">导出当前地区库</button><button class="button button-primary" @click="add">新增当前层级地区</button></div><p v-if="error" class="region-error" role="alert">{{ error }}</p><p v-if="notice" class="region-success" role="status">{{ notice }}</p><section class="regions-box" v-if="stats"><strong>版本 {{ stats.revision }} · {{ stats.total.toLocaleString() }} 个地区节点</strong><p>{{ stats.sourceVersion }} · {{ stats.source }}</p><p>国内底库包含街道乡镇；海外及部分地区仅到已有层级。数据不是实时更新，缺失地区可补录或导入。</p></section><div class="regions-layout"><section class="regions-box"><h2>地区浏览</h2><nav class="regions-path"><button @click="browse(null)">国家/地区</button><button v-for="r in trail" :key="r.code" @click="browse(r)">{{ r.name }} ›</button></nav><div class="regions-search"><input v-model="query" placeholder="搜索名称或代码" @keydown.enter="page=1;load()"/><button class="button button-primary" @click="page=1;load()">查询</button></div><p v-if="loading">读取中…</p><div v-for="r in rows" :key="r.code" class="regions-row"><div><strong>{{ r.name }}</strong><small>{{ levels[r.level] }} · {{ r.code }} · {{ r.available?'可选择':r.enabled?'上级已停用':'已停用' }}</small><small v-if="query">{{ r.label }}</small></div><div class="regions-row-actions"><button v-if="r.level!=='street'" @click="browse(r)">下级</button><button @click="edit(r)">编辑</button><button :disabled="busy" @click="prepare([{code:r.code,parentCode:r.parentCode,name:r.name,level:r.level,enabled:!r.enabled}])">{{ r.enabled?'停用':'启用' }}</button></div></div><p v-if="!rows.length&&!loading">暂无地区，可新增或调整查询条件。</p><footer><button :disabled="page<=1||loading" @click="page--;load()">上一页</button><span>第 {{ page }} 页</span><button :disabled="!hasMore||loading" @click="page++;load()">下一页</button></footer></section><section class="regions-box"><h2>更新地区库</h2><label>来源说明<input v-model="source" maxlength="300"/></label><label>数据版本 / 截止日期<input v-model="sourceVersion" maxlength="80"/></label><div v-if="form" class="regions-editor"><h3>新增 / 编辑地区</h3><p>上级：{{ form.parentCode || '无（国家/地区）' }}</p><label>唯一代码<input v-model="form.code" maxlength="50" placeholder="如 CN-430102001"/></label><label>名称<input v-model="form.name" maxlength="80"/></label><label>层级<select v-model="form.level"><option v-for="(name,key) in levels" :value="key" :key="key">{{ name }}</option></select></label><label class="regions-check"><input type="checkbox" v-model="form.enabled"/>启用</label><button class="button button-primary" :disabled="busy" @click="prepare([form])">预览修改</button></div><h3>批量导入 JSON</h3><p>支持导出的地区库文件和原始 pcas 省市区街道数组；文件不超过20MB。</p><p>默认仅新增，相同代码保留原记录。原始 pcas 文件始终仅补充新增，保留现有国内与海外地区。</p><label>标准化文件更新方式<select v-model="importMode" :disabled="busy" @change="preview=null"><option value="preserve">仅新增，保留已有地区（默认）</option><option value="merge">合并新增与修改，保留其他地区</option><option value="replace">整库更新，停用文件未包含的旧地区</option></select></label><p v-if="importMode==='replace'">整库更新会停用文件中未列出的地区；请核对预览中的修改与停用数量后再确认。</p><input type="file" accept=".json,application/json" :disabled="busy" @change="importFile"/><div v-if="preview" class="regions-preview"><h3>待确认变更</h3><p>{{ preview.sourceVersion }}</p><p>新增 {{ preview.added }} · 修改 {{ preview.changed }} · 停用 {{ preview.disabled }}<span v-if="preview.conflictPolicy==='preserve'"> · 保留已有 {{ preview.keptExisting || 0 }}</span><br/>更新后共 {{ preview.total.toLocaleString() }} 条</p><p>预览15分钟有效；确认前不会改变现有地区库。</p><button class="button button-primary" :disabled="busy" @click="apply">{{ busy?'正在更新…':'确认应用更新' }}</button><button class="button button-secondary" :disabled="busy" @click="preview=null">取消</button></div></section></div></div></template>
<style scoped>
.regions-toolbar,.regions-search,.regions-path,.regions-row-actions{display:flex;gap:8px;flex-wrap:wrap}.regions-toolbar{margin:20px 0}.regions-layout{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(300px,1fr);gap:20px}.regions-box{background:#fff;border:1px solid #dce5f0;border-radius:16px;padding:22px;margin-bottom:20px;min-width:0}.regions-box h2{font-size:20px;margin:0 0 18px}.regions-box h3{font-size:17px}.regions-box p{font-size:14px;color:#718199;line-height:1.7;overflow-wrap:anywhere}.regions-box input:not([type=checkbox]),.regions-box select{width:100%;box-sizing:border-box;min-width:0;padding:11px;border:1px solid #d8e1ed;border-radius:8px;font:inherit;font-size:14px}.regions-box label{display:block;font-size:14px;margin:14px 0}.regions-box label input,.regions-box label select{margin-top:7px}.regions-search{margin:15px 0}.regions-search input{flex:1}.regions-row{display:flex;align-items:center;gap:12px;justify-content:space-between;padding:14px 0;border-bottom:1px solid #edf1f6;font-size:14px}.regions-row>div:first-child{min-width:0;flex:1;overflow-wrap:anywhere}.regions-row small{display:block;color:#7a8a9f;line-height:1.7;margin-top:3px}.regions-box button:not(.button){border:1px solid #dce5ef;border-radius:7px;background:#f6f9fd;color:#23486d;padding:8px 10px;font-size:14px;cursor:pointer}.regions-box footer{display:flex;justify-content:flex-end;gap:10px;align-items:center;font-size:14px;margin-top:20px}.regions-editor{padding-bottom:20px;border-bottom:1px solid #e5ebf4}.regions-preview{margin-top:20px;padding:16px;background:#edf4fd;border-radius:12px}.regions-preview button{margin:4px}.regions-box .regions-check{display:flex;align-items:center;gap:8px}.region-error{color:#b03131}.region-success{color:#176551}@media(max-width:1100px){.regions-layout{grid-template-columns:1fr}}@media(max-width:600px){.regions-row{align-items:flex-start;flex-direction:column}}
</style>
